    21	type MoneyRequestRouteName =
    22	    | typeof SCREENS.MONEY_REQUEST.CREATE
    23	    | typeof SCREENS.MONEY_REQUEST.STEP_DISTANCE
    24	    | typeof SCREENS.MONEY_REQUEST.STEP_AMOUNT
    25	    | typeof SCREENS.MONEY_REQUEST.STEP_WAYPOINT
