    38	    | typeof SCREENS.MONEY_REQUEST.STEP_SEND_FROM
    39	    | typeof SCREENS.MONEY_REQUEST.STEP_COMPANY_INFO;
    40	
    41	type Route<T extends MoneyRequestRouteName> = RouteProp<MoneyRequestNavigatorParamList, T>;
    42	
    43	type WithFullTransactionOrNotFoundProps<T extends MoneyRequestRouteName> = WithFullTransactionOrNotFoundOnyxProps & {route: Route<T>};
    44	
    45	export default function <TProps extends WithFullTransactionOrNotFoundProps<MoneyRequestRouteName>, TRef>(WrappedComponent: ComponentType<TProps & RefAttributes<TRef>>) {
    46	    // eslint-disable-next-line rulesdir/no-negated-variables
    47	    function WithFullTransactionOrNotFound(props: TProps, ref: ForwardedRef<TRef>) {
    48	        const transactionID = props.transaction?.transactionID;
    49	
    50	        const isFocused = useIsFocused();
    51	
    52	        // If the transaction does not have a transactionID, then the transaction no longer exists in Onyx as a full transaction and the not-found page should be shown.
    53	        // In addition, the not-found page should be shown only if the component screen's route is active (i.e. is focused).
    54	        // This is to prevent it from showing when the modal is being dismissed while navigating to a different route (e.g. on requesting money).
    55	        if (!transactionID) {
    56	            return <FullPageNotFoundView shouldShow={isFocused} />;
    57	        }
    58	
    59	        return (
    60	            <WrappedComponent
    61	                // eslint-disable-next-line react/jsx-props-no-spreading
    62	                {...props}
    63	                ref={ref}
    64	            />
    65	        );
    66	    }
    67	
    68	    WithFullTransactionOrNotFound.displayName = `withFullTransactionOrNotFound(${getComponentDisplayName(WrappedComponent)})`;
    69	
    70	    return withOnyx<TProps & RefAttributes<TRef>, WithFullTransactionOrNotFoundOnyxProps>({
    71	        transaction: {
    72	            key: ({route}) => {
    73	                const transactionID = route.params.transactionID ?? -1;
    74	                const userAction = 'action' in route.params && route.params.action ? route.params.action : CONST.IOU.ACTION.CREATE;
    75	
    76	                if (IOUUtils.shouldUseTransactionDraft(userAction)) {
    77	                    return `${ONYXKEYS.COLLECTION.TRANSACTION_DRAFT}${transactionID}` as `${typeof ONYXKEYS.COLLECTION.TRANSACTION}${string}`;
    78	                }
    79	                return `${ONYXKEYS.COLLECTION.TRANSACTION}${transactionID}`;
    80	            },
    81	        },
    82	    })(forwardRef(WithFullTransactionOrNotFound));
    83	}
    84	
    85	export type {WithFullTransactionOrNotFoundProps};
